nta.declaration:
const int n = 3;

// Coordinates
int[0,n-1] x = 0;
int[0,n-1] y = 0;

int[0,1] strategy[n][n][4];

clock total_time;
int battery = 100;

int move_time = 5;
int turn_time = 1;

const int FORWARD = 0;
const int TURN = 1;
const int BOUNDS = -1;

bool pathComplete = false;

const int UNSEEN = -1;
const int ANY = 2;

int turnc = 0;
int movec = 0;

template.declaration:
clock t;
int[0,3] d = 0;
bool visited[n][n];
bool seen[n][n][4];

bool wall() {
    if (d == 0 && y == n-1) return true;
    if (d == 1 && x == n-1) return true;
    if (d == 2 && y == 0) return true;
    if (d == 3 && x == 0) return true;
    return false;
}

int getAction() {
    //if (x == 0 && y == 0 && d == 0) return FORWARD;
    //if (x == 0 && y == 1 && d == 0) return FORWARD;
    //if (x == 0 && y == 2 && d == 0) return TURN;
    //if (x == 0 && y == 2 && d == 1) return FORWARD;
    if (wall()) return TURN;

    if (seen[x][y][d]) {
        return strategy[x][y][d];
    }

    return ANY;
}

bool goal = false;

void move() {
    strategy[x][y][d] = FORWARD;
    seen[x][y][d] = true;

    if (d == 0) y++;
    else if (d == 1) x++;
    else if (d == 2) y--;
    else if (d == 3) x--;

    visited[x][y] = true;

    if (x == n-1 && y == n-1) {
        goal = true;
    }
}

void turn() {
    strategy[x][y][d] = TURN;
    seen[x][y][d] = true;
    d = (d + 1) % 4;
}
